import clsx from 'clsx';
import React, { ReactNode, forwardRef, ElementType, ReactElement } from 'react';
import { isElement } from 'react-is';

import { ChevronDownSmallIcon } from '@dynatrace/strato-icons';

import { _AccordionActions } from './accordion-state.js';
import {
  accordionTriggerIconCSS,
  accordionTriggerIconEndCSS,
  accordionTriggerIconExpandedCSS,
  accordionTriggerIconStartCSS,
} from './Accordion.sty.js';
import { AccordionSectionContent } from './AccordionSectionContent.js';
import { AccordionSectionLabel } from './AccordionSectionLabel.js';
import { useAccordionContext } from './contexts/AccordionContext.js';
import { AccordionSectionContext } from './contexts/AccordionSectionContext.js';
import { Button } from '../../buttons/button/Button.js';
import { _useId } from '../../core/hooks/useId.js';
import type { DataTestId } from '../../core/types/data-props.js';
import type { PolymorphicComponentProps } from '../../core/types/polymorph.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import type { WithChildren } from '../../core/types/with-children.js';
import { Flex } from '../../layouts-core/flex/Flex.js';
import { fieldColorsCSS } from '../../styles/field.sty.js';

// #region Typings
// Merge own props with others inherited from the underlying element type
export type AccordionSectionProps<E extends ElementType> =
  PolymorphicComponentProps<E, AccordionSectionOwnProps>;
export interface AccordionSectionOwnProps
  extends WithChildren,
    StylingProps,
    DataTestId {
  /**
   * Determines whether the section is disabled.
   * @defaultValue false
   */
  disabled?: boolean;

  /** Unique identifier of a section within an accordion. */
  id: string | number;

  /**
   * Defines if the sections content will be kept in the DOM, even if the content
   * is not shown to the user.
   * @defaultValue false
   */
  keepMounted?: boolean;

  /**
   * The color of the accordion section.
   * Setting the color affects the button, label and content.
   */
  color?: 'neutral' | 'primary' | 'success' | 'warning' | 'critical';
}

type AccordionSectionSlots = {
  label?: ReactNode;
  content?: ReactNode;
};
//#endregion Typings

/** Iterates over child nodes to extract specific component slots. */
function getAccordionSectionSlots(children: React.ReactNode) {
  const slots: AccordionSectionSlots = {};

  React.Children.forEach(children, (child) => {
    if (isElement(child)) {
      switch (child.type) {
        case AccordionSectionLabel:
          slots.label = child;
          break;
        case AccordionSectionContent:
          slots.content = child;
          break;
      }
    }
  });

  return slots;
}

export function isAccordionSectionChild(
  node: unknown,
): node is React.ReactElement<AccordionSectionOwnProps> {
  return isElement(node) && node.props.id !== undefined;
}

/** Accordion Section component */
export const AccordionSection: <E extends ElementType = 'div'>(
  props: AccordionSectionProps<E>,
) => ReactElement | null = /* @__PURE__ */ forwardRef(
  <E extends ElementType>(
    props: AccordionSectionProps<E>,
    forwardedRef: typeof props.ref,
  ) => {
    const {
      disabled = false,
      id,
      children,
      className: consumerClassName,
      style: consumerStyle,
      keepMounted = false,
      'data-testid': dataTestId,
      as,
      ...remainingProps
    }: AccordionSectionProps<E> = props;

    const slots = getAccordionSectionSlots(children);
    const { triggerPosition, interactive, color, size, state, dispatch } =
      useAccordionContext();

    const sectionColor = props.color ?? color;

    const triggerId = _useId();
    const contentId = _useId();
    const triggerIsStart = triggerPosition === 'start';

    const isExpanded = state.expanded.has(id);

    const labelId = _useId({ prefix: 'accordion' });

    const trigger = (
      <Button
        id={triggerId}
        onClick={() => {
          if (!interactive) {
            dispatch({ type: _AccordionActions.TOGGLE_SECTION, payload: id });
          }
        }}
        color={sectionColor}
        size={size}
        disabled={disabled}
        aria-labelledby={labelId}
        aria-expanded={isExpanded}
        aria-controls={contentId}
      >
        <Button.Prefix>
          <ChevronDownSmallIcon
            className={clsx(accordionTriggerIconCSS, {
              [accordionTriggerIconStartCSS]: triggerIsStart === true,
              [accordionTriggerIconEndCSS]: triggerIsStart === false,
              [accordionTriggerIconExpandedCSS]: isExpanded,
            })}
          />
        </Button.Prefix>
      </Button>
    );
    const Section = as ?? 'div';
    return (
      <Section
        data-testid={dataTestId}
        ref={forwardedRef}
        className={clsx(
          fieldColorsCSS({ color: sectionColor }),
          consumerClassName,
        )}
        style={consumerStyle}
        {...remainingProps}
      >
        {(slots.label || slots.content) && (
          <AccordionSectionContext.Provider
            value={{
              triggerIsStart,
              triggerId,
              contentId,
              isExpanded,
              keepMounted,
              size,
            }}
          >
            <Flex
              flexDirection="row"
              alignItems="center"
              justifyContent={triggerIsStart ? undefined : 'space-between'}
              gap={size === 'default' ? 8 : 4}
              id={labelId}
              onClick={() => {
                if (interactive && !disabled) {
                  dispatch({
                    type: _AccordionActions.TOGGLE_SECTION,
                    payload: id,
                  });
                }
              }}
              style={{
                cursor: interactive && !disabled ? 'pointer' : undefined,
              }}
            >
              {triggerIsStart && trigger}
              {slots.label}
              {!triggerIsStart && trigger}
            </Flex>
            {slots.content}
          </AccordionSectionContext.Provider>
        )}
      </Section>
    );
  },
);

(
  AccordionSection as typeof AccordionSection & { displayName: string }
).displayName = 'Accordion.Section';
